    if o:
        p.append(ONES[o])
    return ' '.join(p)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for size, lab in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        g = n // size
        n = n % size
        if g:
            out.append('bin' if (lab == 'bin' and g == 1) else w3(g) + ' ' + lab)
    if n:
        out.append(w3(n))
    return ' '.join(out)

