        owe, clear = [], []
        for code, key, lab in (('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')):
            b = d.get(key)
            if not isinstance(b, dict) or not b:
                continue
            (owe if f(b, 'remainingDebt') > 0 else clear).append((code, b, lab))
        tlb = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else {}
        tl_total = max(f(tlb, 'totalDebt'), 0.0)
        parts = []
