        "method": {"type": "string", "default": "POST"},
        "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
        "body": {
         "type": "object",
         "properties": {
          "data": {
           "type": "object",
           "default": {"cardNumber": "{{sel_card}}", "newStatementWeek": "{{new_week}}", "statementDay": "{{stmt_day}}"},
           "properties": {
            "cardNumber": {"type": "string", "default": "{{sel_card}}"},
            "newStatementWeek": {"type": "string", "default": "{{new_week}}"},
            "statementDay": {"type": "string", "default": "{{stmt_day}}"}
           },
           "required": ["cardNumber", "newStatementWeek", "statementDay"]
          }
         },
         "required": ["data"]
        }
       }
      }
     },
     "post_process_code": "import datetime\nMONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']\n\ndef sd(s):\n    x = datetime.datetime.strptime(str(s).strip()[:10], '%d.%m.%Y').date()\n    return str(x.day) + ' ' + MONTHS[x.month - 1] + ' ' + str(x.year)\n\ntry:\n    result.pop('header', None)\n    sc = str(result.get('status_code') or '')\n    body = result.get('data') if isinstance(result.get('data'), dict) else {}\n    d = body.get('data') if isinstance(body.get('data'), dict) else {}\n    if sc.startswith('2') and str(d.get('responseCode')) in ('0', '0.0') and d.get('statementDate') and d.get('statementDueDate'):\n        w = str(vars.get('new_week') or '')\n        vars['new_stmt_date'] = sd(d.get('statementDate'))\n        vars['new_due_date'] = sd(d.get('statementDueDate'))\n        vars['confirm_text'] = (vars.get('joint_text') or '') + 'Yeni hesap kesim haftanız her ayın ' + w + '. haftası olacak. Yeni hesap kesim tarihiniz ' + vars['new_stmt_date'] + ', son ödeme tarihiniz ' + vars['new_due_date'] + ' olacak. Onaylıyor musunuz?'\n        vars['preview_state'] = 'ok'\n    else:\n        vars['preview_state'] = 'error'\n    result['data'] = {'preview_state': vars['preview_state']}\nexcept Exception:\n    vars['preview_state'] = 'error'\nvars['confirm_answer'] = 'stay'\n"
    }
   ],
   "transitions": [
    {"target_node": "week_confirm", "description": "Preview ready", "condition": {"logic": "or", "conditions": [{"variable": "preview_state", "operator": "equals", "operand": "ok"}]}},
    {"target_node": "end_week_error", "description": "always", "condition": {"operator": "always"}}
   ]
  },
  "week_confirm": {
   "name": "week_confirm",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "{{confirm_text}}"},
   "task_message": "You read the new dates and asked for confirmation. Only a clear 'evet' counts as yes. A hedged answer such as 'olur herhalde', 'galiba' or 'belki' is not a yes. Even if the caller says to just do it, the change is made only after the clear yes. Change nothing yourself. Call end_call only right after you said goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after the goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "confirm_answer", "type": "string", "enum_values": ["stay", "yes", "no", "unclear"], "description": "yes: a clear, unhedged yes (evet, onaylıyorum); no: refuses; unclear: a hedged or vague answer (olur herhalde, galiba, belki) or an answer to something else; stay: a question or a repeat request.", "min_confidence": 0.7}
   ],
   "max_node_turns": 6,
   "max_turn_transition": "end_tries",
   "transitions": [
    {"target_node": "week_change", "description": "Clear yes", "condition": {"logic": "or", "conditions": [{"variable": "confirm_answer", "operator": "equals", "operand": "yes"}]}},
    {"target_node": "end_menu", "description": "No", "condition": {"logic": "or", "conditions": [{"variable": "confirm_answer", "operator": "equals", "operand": "no"}]}},
    {"target_node": "confirm_count", "description": "Hedged answer", "condition": {"logic": "or", "conditions": [{"variable": "confirm_answer", "operator": "equals", "operand": "unclear"}]}}
   ]
  },
  "confirm_count": {
   "name": "confirm_count",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "week_confirm",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {"type": "string", "default": "try:\n    n = int(vars.get('confirm_count') or 0) + 1\n    vars['confirm_count'] = str(n)\n    vars['confirm_route'] = 'tries' if n >= 3 else 'again'\nexcept Exception:\n    vars['confirm_route'] = 'tries'\nvars['confirm_answer'] = 'stay'\n"},
        "timeout_ms": {"type": "number", "default": 10000}
       }
      }
     }
    }
   ],
   "transitions": [
    {"target_node": "end_tries", "description": "Three tries used up", "condition": {"logic": "or", "conditions": [{"variable": "confirm_route", "operator": "equals", "operand": "tries"}]}},
    {"target_node": "week_confirm", "description": "always", "condition": {"operator": "always"}}
   ]
  },
  "week_change": {
   "name": "week_change",
   "node_type": "api_request",
   "passthrough": true,
   "passthrough_default_transition": "end_week_error",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "config": {"timeoutMs": 20000, "maxRetries": 0},
     "function": {
      "name": "statement.week.change",
      "handler": "__function__:api_call",
      "description": "Make the statement week change.",
      "parameters": {
       "type": "object",
       "properties": {
        "url": {"type": "string", "default": "https://statement-mock.guntop-mockbank.workers.dev/voice/v1/statement.week.change"},
        "method": {"type": "string", "default": "POST"},
        "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
        "body": {
         "type": "object",
         "properties": {
          "data": {
           "type": "object",
           "default": {"cardNumber": "{{sel_card}}", "newStatementWeek": "{{new_week}}", "statementDay": "{{stmt_day}}"},
           "properties": {
            "cardNumber": {"type": "string", "default": "{{sel_card}}"},
            "newStatementWeek": {"type": "string", "default": "{{new_week}}"},
            "statementDay": {"type": "string", "default": "{{stmt_day}}"}
           },
           "required": ["cardNumber", "newStatementWeek", "statementDay"]
          }
         },
         "required": ["data"]
        }
       }
