        l4 = str(vars.get('sel_l4') or d.get('cardNumberLast4') or '')[-4:]
        name = str(vars.get('sel_name') or d.get('productName') or '').strip()
        sl4 = ' '.join(DIG[int(ch)] for ch in l4 if ch.isdigit())
        intro = 'Sonu ' + sl4 + ' ile biten ' + (name + ' kartınıza' if name else 'kartınıza')
        intro_k = 'Sonu ' + sl4 + ' ile biten ' + (name + ' kartınızın' if name else 'kartınızın')
        sd, lp, nsd = pdate(d.get('statementDate')), pdate(d.get('lastPayDate')), pdate(d.get('nextStatementDate'))
        owe, clear = [], []
        for code, key, lab in (('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')):
            b = d.get(key)
            if not isinstance(b, dict) or not b:
                continue
            (owe if f(b, 'remainingDebt') > 0 else clear).append((code, b, lab))
        tlb = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else {}
        tl_total = max(f(tlb, 'totalDebt'), 0.0)
        parts = []
        if nsd and nsd == today:
            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. Gelecek dönemler dahil toplam borcunuz ' + cop(amount(tl_total, 'TL')) + '.')
        vars['no_debt'] = 'yes' if (sd is None or str(d.get('statementPaymentStatus')).upper() == 'NO_DEBT' or not owe) else 'no'
        if sd is None:
            parts.append(intro + ' ait kesilmiş bir ekstre bulunmadığı için borcunuz bulunmamaktadır.')
        elif str(d.get('statementPaymentStatus')).upper() == 'NO_DEBT' or not owe:
            parts.append(intro_k + ' ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz ' + cop(amount(tl_total, 'TL')) + '.')
            if lp:
                parts.append('Son ödeme tarihiniz ' + sdate(lp) + ' olacaktır.')
        else:
            first = True
            for code, b, lab in owe:
                lead = (intro + ' ait ' + sdate(sd) + ' tarihinde kesilen ekstre ') if first else ''
                first = False
                X, Z, Y, T = amount(f(b, 'statementDebt'), code), amount(f(b, 'minPayment'), code), amount(f(b, 'remainingDebt'), code), amount(f(b, 'remainingMinPayment'), code)
                if code == 'TL':
                    rmp, mp = f(b, 'remainingMinPayment'), f(b, 'minPayment')
                    if rmp <= 0:
                        s = 'Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + cop(Y) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    elif rmp >= mp:
                        s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + cop(Z) + '.'
                    else:
                        s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + cop(T) + '.'
                else:
                    s = lab + ' borcunuz ' + X + ', kalan toplam borcunuz ' + Y + ', ödenmesi gereken minimum tutar ' + cop(Z) + '.'
                parts.append(lead + s)
            if clear:
                labs = [c[2] for c in clear]
                parts.append((labs[0] if len(labs) == 1 else ', '.join(labs[:-1]) + ' ve ' + labs[-1]) + ' borcunuz bulunmamaktadır.')
            if lp and today > lp and str(d.get('automaticPaymentFlag')).upper() == 'Y' and f(tlb, 'remainAutomaticPaymentAmount') > 0:
                parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + cop(amount(f(tlb, 'remainAutomaticPaymentAmount'), 'TL')) + '.')
            if lp:
                if lp == today:
