                elif today > lp:
                    parts.append('Borçlarınız için son ödeme tarihiniz olan ' + sdate(lp) + ' geçmiştir. Gelecek dönemler dahil toplam borcunuz ' + cop(amount(tl_total, 'TL')) + '.')
                else:
                    parts.append('Borçlarınız için son ödeme tarihiniz ' + date_cop(lp) + '.')
        vars['reading_text'] = ' '.join(parts)
        vars['stmt_date'] = str(d.get('statementDate') or '')
        vars['currency_type'] = owe[0][0] if owe else 'TL'
