        vars['no_debt'] = 'yes' if (sd is None or str(d.get('statementPaymentStatus')).upper() == 'NO_DEBT' or not owe) else 'no'
        if sd is None:
            parts.append(intro + ' ait kesilmiş bir ekstre bulunmadığı için borcunuz bulunmamaktadır.')
        elif str(d.get('statementPaymentStatus')).upper() == 'NO_DEBT' or not owe:
            parts.append(intro_k + ' ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz ' + cop(amount(tl_total, 'TL')) + '.')
            if lp:
                parts.append('Son ödeme tarihiniz ' + sdate(lp) + ' olacaktır.')
        else:
            first = True
            for code, b, lab in owe:
                lead = (intro + ' ait ' + sdate(sd) + ' tarihinde kesilen ekstre ') if first else ''
                first = False
                X, Z, Y, T = amount(f(b, 'statementDebt'), code), amount(f(b, 'minPayment'), code), amount(f(b, 'remainingDebt'), code), amount(f(b, 'remainingMinPayment'), code)
                if code == 'TL':
