MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']

def sd(s):
    try:
        x = datetime.datetime.strptime(str(s).strip()[:10], '%d.%m.%Y').date()
        return str(x.day) + ' ' + MONTHS[x.month - 1] + ' ' + str(x.year)
    except Exception:
        return ''

try:
    result.pop('header', None)
    sc = str(result.get('status_code') or '')
    body = result.get('data') if isinstance(result.get('data'), dict) else {}
    d = body.get('data') if isinstance(body.get('data'), dict) else {}
    cur = str(d.get('statementWeek') or '').strip()
    if not sc.startswith('2') or cur not in ('1', '2', '3', '4'):
        vars['week_state'] = 'error'
    else:
        name = str(vars.get('sel_name') or d.get('productName') or '').strip()
        card = (name + ' kartınızın') if name else 'Kartınızın'
        vars['cur_week'] = cur
        vars['stmt_day'] = str(d.get('statementDay') or '')
        intro = 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ' + card + ' hesap kesim tarihi her ayın ' + cur + '. haftası olarak tanımlı. Bir sonraki hesap kesim tarihiniz ' + sd(d.get('nextStatementDate')) + ', son ödeme tarihiniz ' + sd(d.get('nextLastPayDate')) + '.'
        rel = str(d.get('relationType') or '').strip().upper()
        other = str(d.get('relatedCardProductName') or '').strip()
        vars['joint_text'] = ''
        if rel in ('M', 'C') and other:
            ol4 = str(d.get('relatedCardNumber') or '')[-4:]
            intro += ' Bu ekstre sonu ' + ' '.join(DIG[int(ch)] for ch in ol4 if ch.isdigit()) + ' ile biten ' + other + ' kartınızla ortaktır.'
            if rel == 'M':
                vars['joint_text'] = 'Bu değişiklik kartınıza bağlı ' + other + ' kartınızı da etkileyecek. '
            else:
                vars['joint_text'] = 'Bu değişiklik kartınızın bağlı olduğu ' + other + ' kartınızı da etkileyecek. '
        vars['week_intro'] = intro + ' Hesap kesim tarihinizi değiştirmek ister misiniz?'
        opts = [w for w in ('1', '2', '3', '4') if w != cur]
        vars['week_options'] = 'Hesap kesim tarihinizi ayın ' + opts[0] + '., ' + opts[1] + '. ya da ' + opts[2] + '. haftasına alabilirim. Hangisini tercih edersiniz?'
        vars['week_prompt'] = vars['week_options']
        vars['week_tries'] = '0'
        vars['confirm_count'] = '0'
        vars['week_state'] = 'ok'
    result['data'] = {'week_state': vars.get('week_state')}
except Exception:
    vars['week_state'] = 'error'
