                lead = (intro + ' ait ' + sdate(sd) + ' tarihinde kesilen ekstre ') if first else ''
                first = False
                X, Z, Y, T = amount(f(b, 'statementDebt'), code), amount(f(b, 'minPayment'), code), amount(f(b, 'remainingDebt'), code), amount(f(b, 'remainingMinPayment'), code)
