DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']

def sd(s):
    try:
        x = datetime.datetime.strptime(str(s).strip()[:10], '%d.%m.%Y').date()
        return str(x.day) + ' ' + MONTHS[x.month - 1] + ' ' + str(x.year)
    except Exception:
        return ''

try:
